Tr.Begin();
string s = "ABZ";
Tr.S("النص صناديق أحرف لها مؤشرات.", "s", s);
string r = "";
Tr.S("نص فارغ نبني فيه الناتج.", "r", r);
for (int i = 0; i < s.Length; i++)
{ //~
    r += (char)((s[i] - 'A' + 2) % 26 + 'A');
    Tr.S("الحرف " + s[i] + " رقمه " + (s[i] - 'A') + "، ومع الإزاحة 2 يصبح " + r[i] + ".", "i", i, "(s[i] - 'A' + 2) % 26", (s[i] - 'A' + 2) % 26, "r", r);
} //~
Tr.Drop("i");
Console.WriteLine(r);
Tr.S("الطباعة: CDB.");
Tr.End();

Tr.Begin();
string s = "level";
Tr.S("النص صناديق أحرف.", "s", s);
bool ok = true;
Tr.S("نفترض أنه متناظر.", "ok", ok);
for (int i = 0; i < s.Length / 2; i++)
{ //~
    Tr.At(4, "نقارن الحرف " + i + " بالحرف المقابل " + (s.Length - 1 - i) + ".", "i", i, "s[i]", s[i], "s[s.Length - 1 - i]", s[s.Length - 1 - i]);
    if (s[i] != s[s.Length - 1 - i])
    { //~
        ok = false;
        Tr.S("لا نصل إلى هنا.", "ok", ok);
    } //~
} //~
Tr.Drop("i");
Console.WriteLine(ok);
Tr.S("الطباعة: True.");
Tr.End();
